r={'status':'UNADOPTED_CANDIDATE_ENGINEERING_REVIEW_DO_NOT_ORDER','source_pcb_sha256':h,'source_schematic_sha256':sha(S/'pendant-xe-minimal.kicad_sch'),'bom_source':str(S/'candidate-mpn-review.csv'),'commands':commands,'origin':'Absolute; placement CSVY=-KiCadY; bottomX not mirrored','copper_layers':6,'files_sha256':{str(f.relative_to(D)):sha(f)for f in sorted(D.rglob('*'))if f.is_file()},'unresolved':['NCU sensor identity selected for evaluation; electrical, land/process and thermal contact qualification incomplete','Q6/Q7 candidate MPN remains DMN2056U-7 with generic raw schematic values','Final size and original battery lead/plug fit unresolved','16h runtime unmeasured','CAM/rotation/via process and all-in5unit cost incomplete','Current integrated3D model belongs to parent PCB and retains genericTH1; standaloneNCU envelope study separate'],'upload_or_order_performed':False};(D/'REVIEW-ONLY.json').write_text(json.dumps(r,indent=2)+'\n');print(D)
